import math

def run(robot, args):
    scene = robot.scene()
    tallest = max([o["h"] for o in [*scene["obstacles"].values(), *scene["objects"].values()]] + [0.0])
    if not robot.pick(args["object"], transit_z=tallest + 0.08):
        return False
    if not robot.place_in_zone("tray", transit_z=tallest + 0.08):
        return False
    robot.home()
    return True
